PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS cortes(id TEXT PRIMARY KEY, quincena TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL, source_hash TEXT NOT NULL, source_name TEXT NOT NULL, expected TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'BORRADOR', validation TEXT);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS personas(corte TEXT NOT NULL REFERENCES cortes(id), matricula TEXT NOT NULL, nombre_search TEXT NOT NULL, tc TEXT NOT NULL, status TEXT NOT NULL, json TEXT NOT NULL CHECK(json_valid(json)), PRIMARY KEY(corte,matricula));
CREATE INDEX IF NOT EXISTS personas_search ON personas(corte,nombre_search);
CREATE TABLE IF NOT EXISTS plazas(corte TEXT NOT NULL REFERENCES cortes(id), plaza TEXT NOT NULL, ocupante TEXT, titular TEXT, puesto TEXT, departamento TEXT, json TEXT NOT NULL CHECK(json_valid(json)), PRIMARY KEY(corte,plaza));
CREATE INDEX IF NOT EXISTS plazas_ocupante ON plazas(corte,ocupante);
CREATE TABLE IF NOT EXISTS antiguedad(corte TEXT NOT NULL REFERENCES cortes(id), matricula TEXT NOT NULL, json TEXT NOT NULL CHECK(json_valid(json)), PRIMARY KEY(corte,matricula));
CREATE TABLE IF NOT EXISTS catalogos(corte TEXT NOT NULL REFERENCES cortes(id), clave TEXT NOT NULL, json TEXT NOT NULL CHECK(json_valid(json)), PRIMARY KEY(corte,clave));
CREATE TABLE IF NOT EXISTS chunks(corte TEXT NOT NULL REFERENCES cortes(id), dataset TEXT NOT NULL, numero INTEGER NOT NULL, hash TEXT NOT NULL, PRIMARY KEY(corte,dataset,numero));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, usuario TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS auth_limits(key TEXT PRIMARY KEY, intentos INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY, corte TEXT, accion TEXT NOT NULL, usuario TEXT NOT NULL, fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS curriculum_files(id TEXT PRIMARY KEY,owner TEXT NOT NULL,recipient TEXT NOT NULL,name TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS curriculum_chunks(file TEXT NOT NULL REFERENCES curriculum_files(id),numero INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(file,numero));
CREATE INDEX IF NOT EXISTS curriculum_owner ON curriculum_files(owner,recipient);
CREATE TABLE IF NOT EXISTS pase_folios(id INTEGER PRIMARY KEY AUTOINCREMENT,request_id TEXT UNIQUE NOT NULL,owner TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contrataciones(id INTEGER PRIMARY KEY AUTOINCREMENT,uuid TEXT NOT NULL UNIQUE,request_key TEXT NOT NULL UNIQUE,creator TEXT NOT NULL,corte TEXT NOT NULL REFERENCES cortes(id),quincena TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'BORRADOR',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),plan TEXT NOT NULL CHECK(json_valid(plan)));
CREATE INDEX IF NOT EXISTS contrataciones_owner ON contrataciones(creator,id);
CREATE INDEX IF NOT EXISTS contrataciones_estado ON contrataciones(estado,id);
CREATE TABLE IF NOT EXISTS contratacion_events(id TEXT PRIMARY KEY,solicitud TEXT NOT NULL REFERENCES contrataciones(uuid),actor TEXT NOT NULL,accion TEXT NOT NULL,fecha TEXT NOT NULL,detalle TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cobertura_jornadas(id TEXT PRIMARY KEY,quincena TEXT NOT NULL,unidad TEXT NOT NULL,nombre TEXT NOT NULL,categorias TEXT NOT NULL,horas REAL NOT NULL,tarifa_centavos INTEGER NOT NULL CHECK(tarifa_centavos>0),presupuesto_centavos INTEGER NOT NULL CHECK(presupuesto_centavos>=0),estado TEXT NOT NULL DEFAULT 'BORRADOR',version INTEGER NOT NULL DEFAULT 1,actualizado_por TEXT NOT NULL,actualizado_en TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cobertura_reservas(solicitud TEXT PRIMARY KEY REFERENCES contrataciones(uuid),jornada TEXT NOT NULL REFERENCES cobertura_jornadas(id),centavos INTEGER NOT NULL CHECK(centavos>0));
CREATE TABLE IF NOT EXISTS cobertura_config_audit(id TEXT PRIMARY KEY,tipo TEXT NOT NULL,registro TEXT NOT NULL,actor TEXT NOT NULL,fecha TEXT NOT NULL,datos TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cobertura_tabuladores(id TEXT PRIMARY KEY,quincena TEXT NOT NULL,nombre TEXT NOT NULL,datos TEXT NOT NULL,hash TEXT NOT NULL,creado_por TEXT NOT NULL,creado_en TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS cobertura_tab_qna ON cobertura_tabuladores(quincena,creado_en);
CREATE TABLE IF NOT EXISTS cobertura_firmantes(owner TEXT NOT NULL,trabajador TEXT NOT NULL,jefe TEXT NOT NULL,dependencia TEXT NOT NULL,PRIMARY KEY(owner,trabajador));
CREATE TRIGGER IF NOT EXISTS cobertura_reglas_fijas BEFORE UPDATE ON cobertura_jornadas WHEN EXISTS(SELECT 1 FROM cobertura_reservas WHERE jornada=OLD.id) BEGIN SELECT RAISE(ABORT,'La jornada tiene presupuesto comprometido'); END;
CREATE TABLE IF NOT EXISTS cobertura_presupuestos(quincena TEXT NOT NULL,unidad TEXT NOT NULL,centavos INTEGER NOT NULL CHECK(centavos>=0),version INTEGER NOT NULL DEFAULT 1,actor TEXT NOT NULL,fecha TEXT NOT NULL,PRIMARY KEY(quincena,unidad));
DROP TRIGGER IF EXISTS cobertura_saldo;
CREATE TRIGGER IF NOT EXISTS cobertura_saldo BEFORE INSERT ON cobertura_reservas BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM cobertura_jornadas WHERE id=NEW.jornada AND estado='AUTORIZADA') OR NEW.centavos+COALESCE((SELECT SUM(r.centavos) FROM cobertura_reservas r JOIN cobertura_jornadas j ON j.id=r.jornada WHERE j.quincena=(SELECT quincena FROM cobertura_jornadas WHERE id=NEW.jornada) AND j.unidad=(SELECT unidad FROM cobertura_jornadas WHERE id=NEW.jornada)),0)>COALESCE((SELECT p.centavos FROM cobertura_presupuestos p JOIN cobertura_jornadas j ON p.quincena=j.quincena AND p.unidad=j.unidad WHERE j.id=NEW.jornada),0) THEN RAISE(ABORT,'Presupuesto insuficiente o jornada no autorizada') END; END;
CREATE TRIGGER IF NOT EXISTS cobertura_presupuesto_minimo BEFORE UPDATE ON cobertura_presupuestos WHEN NEW.centavos<COALESCE((SELECT SUM(r.centavos) FROM cobertura_reservas r JOIN cobertura_jornadas j ON r.jornada=j.id WHERE j.quincena=OLD.quincena AND j.unidad=OLD.unidad),0) BEGIN SELECT RAISE(ABORT,'Presupuesto inferior al comprometido'); END;
